package com.dreamfacilities.servlet;
import com.dreamfacilities.dao.FeedbackDAO; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/admin") public class AdminServlet extends HttpServlet {protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{if(q.getSession(false)==null||q.getSession(false).getAttribute("adminUser")==null){r.sendRedirect(q.getContextPath()+"/admin/login");return;}try{q.setAttribute("feedbacks",new FeedbackDAO().find(q.getParameter("q"),0,true));}catch(Exception e){q.setAttribute("error","Unable to load feedback. Check the database connection.");}q.getRequestDispatcher("/WEB-INF/views/admin.jsp").forward(q,r);}protected void doPost(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{if(q.getSession(false)==null||q.getSession(false).getAttribute("adminUser")==null){r.sendError(401);return;}try{FeedbackDAO d=new FeedbackDAO();String action=q.getParameter("action");int id=Integer.parseInt(q.getParameter("id"));if("approve".equals(action))d.approve(id,true);else if("hide".equals(action))d.approve(id,false);else if("delete".equals(action))d.delete(id);}catch(Exception ignored){}r.sendRedirect(q.getContextPath()+"/admin");} }
